function ready(s, l) { const n = l.need; return (!n.meet || s.done[l.id]) && (!n.fish || s.caught >= n.fish) && (!n.orbs || orbCount(s) >= n.orbs) && (!n.pay || s.mon >= n.pay) && (!n.read || s.read); }
function objective(s) {
  if (s.final) return "All nine lanterns are lit. The country is yours to wander.";
  const l = LANTERNS.find((x) => !s.lit[x.id]);
  if (!l) return "Every lantern is lit but one. Go to the Lantern Shrine.";
  if (!s.took[l.id]) return `Talk to ${nameOf(l.who)} about the ${l.name} lantern.`;
  if (ready(s, l)) return `Go back to ${nameOf(l.who)} and light the ${l.name} lantern.`;
  const n = l.need, bits = [];
  if (n.meet && !s.done[l.id]) bits.push(`see ${nameOf(n.meet)}`); if (n.fish && s.caught < n.fish) bits.push(`fish ${s.caught}/${n.fish}`); if (n.orbs) bits.push(`foxfire ${orbCount(s)}/${n.orbs}`); if (n.pay) bits.push(`mon ${s.mon}/${n.pay}`); if (n.read && !s.read) bits.push("read a story");
  return `${l.name}: ${bits.join(", ")}.`;
}

